create table if not exists public.agent_tool_registry (
id uuid primary key default gen_random_uuid(),app text not null,tool_key text not null,domain text not null,display_name text not null,description text not null,permission text,action_type text not null check(action_type in('read','write','destructive')),requires_confirmation boolean not null default false,destructive boolean not null default false,handler text not null,enabled boolean not null default true,args_schema jsonb not null default '{}'::jsonb,result_contract text,updated_at timestamptz not null default now(),unique(app,tool_key));
create index if not exists agent_tool_registry_app_domain_idx on public.agent_tool_registry(app,domain,enabled);
revoke all on public.agent_tool_registry from public,anon,authenticated;
grant select on public.agent_tool_registry to service_role;

